// Sunbot payment schedule overlay 12/09/2026
(function(){
'use strict';
const ANNUAL_SITE=5000000, MOD=31700000, left={9:9,10:8,11:7,12:6,1:5,2:4,3:3,4:2,5:1}, names={9:'Tháng 9',10:'Tháng 10',11:'Tháng 11',12:'Tháng 12',1:'Tháng 1',2:'Tháng 2',3:'Tháng 3',4:'Tháng 4',5:'Tháng 5'};
const N=(id,d=0)=>Number(document.getElementById(id)?.value||d), M=n=>typeof mil==='function'?mil(n):(n/1e6).toFixed(1)+' triệu', T=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v};
function scope(){return document.querySelector('#contractScopeButtons .btn.active')?.dataset.scope||'same_unit'}
function trainFee(t,p){t=Math.max(0,Math.round(t||0));if(!t)return 0;if(t>50)return null;const b=Math.ceil(Math.max(t-20,0)/10);return p===2?19000000+b*7000000:11000000+b*4000000}
function chunks(n){return ({9:[2,2,2,3],8:[2,2,2,2],7:[2,2,3],6:[2,2,2],5:[3,2],4:[2,2],3:[3],2:[2],1:[1]})[n]}
function nx(m){return m===12?1:m+1} function label(s,n){let e=s;for(let i=1;i<n;i++)e=nx(e);return n===1?names[s]:`${names[s]}–${String(names[e]).replace('Tháng ','')}`}
function add(){const mo=document.getElementById('months'),box=mo?.closest('.control');if(box&&!document.getElementById('startMonthControl')){const d=document.createElement('div');d.id='startMonthControl';d.className='control';d.innerHTML='<div class="head"><label>Tháng bắt đầu triển khai</label><span class="value" id="startMonthVal">Tháng 9</span></div><select class="input" id="startMonth"><option value="9">Tháng 9 — đầu năm học</option><option value="10">Tháng 10</option><option value="11">Tháng 11</option><option value="12">Tháng 12</option><option value="1">Tháng 1 — học kỳ II</option><option value="2">Tháng 2</option><option value="3">Tháng 3</option><option value="4">Tháng 4</option><option value="5">Tháng 5</option></select><div class="sub">Tự tính số tháng còn lại đến hết tháng 5 và chia kỳ thanh toán 2–3 tháng.</div>';box.before(d);const l=box.querySelector('label');if(l)l.textContent='Số tháng triển khai còn lại trong năm học';mo.min=1;mo.max=9;mo.disabled=true;const s=box.querySelector('.sub');if(s)s.textContent='Tự động tính từ tháng bắt đầu; không nhập tay.'}
const cmp=document.getElementById('compareBody')?.closest('table');if(cmp&&!document.getElementById('paymentScheduleBox')){const d=document.createElement('div');d.id='paymentScheduleBox';d.className='summary';d.innerHTML='<h4>Lịch thanh toán dự kiến</h4><p id="payIntro"></p><table class="table"><thead><tr><th>Kỳ</th><th>Thời gian</th><th>Thanh toán Sunbot</th></tr></thead><tbody id="payBody"></tbody></table><p id="payAfter" class="sub"></p>';cmp.before(d)}}
function state(){const start=Number(document.getElementById('startMonth')?.value||9),months=left[start],c=N('children'),cs=N('classSize',20),f=N('fee'),l=N('lessons',4),tr=N('teacherRate'),points=N('campusCount',1),p=typeof programs==='undefined'?1:Number(programs)||1,md=typeof mode==='undefined'?'own':mode,ln=typeof launch==='undefined'?'new':launch,tm=typeof term==='undefined'?24:Number(term)||24,sv=typeof service==='undefined'?0:Number(service)||0,manual=N('classCountInput'),classes=manual?Math.max(1,Math.round(manual)):Math.ceil(c/cs),trainers=N('trainingTeacherCount'),assess=N('teacherCount'),rooms=typeof roomCount==='function'?roomCount(c):Math.max(c<=300?1:c<=800?2:3,points),rv=rooms*MOD,share=md==='own'?0:md==='provide'?1:N('capitalShare',50)/100,schoolInvest=rv*(1-share),equipmentSale=md!=='provide'?schoolInvest:0,extraInvest=md!=='own'&&typeof extra!=='undefined'&&extra?rv*N('extraPct',10)/100:0,pf=typeof feeByScale==='function'?feeByScale(c,l,months):null,training=ln==='new'?trainFee(trainers,p):0,assessment=ln==='new'?assess*500000*p:0,site=scope()==='same_unit'?Math.max(points-1,0)*ANNUAL_SITE*months/9:0,serviceMonthly=typeof servicePlans!=='undefined'&&servicePlans[sv]?c*servicePlans[sv].sunbotFeeMonthly:0,serviceFee=serviceMonthly*months,recoveryMonthly=(rv*share+extraInvest)*1.3/tm,recovery=recoveryMonthly*months,parent=c*f*l*months*p+c*sv*1000*months,teacher=classes*l*months*tr*p,other=N('otherCost'),blocked=scope()==='multi_school'||c>800||training===null;return{start,months,c,f,l,tr,points,p,md,ln,tm,sv,classes,rv,share,schoolInvest,equipmentSale,pf,training,assessment,site,serviceMonthly,serviceFee,recoveryMonthly,recovery,parent,teacher,other,blocked,remainingMonths:Math.max(tm-months,0)}}
function update(){add();const sm=document.getElementById('startMonth'),mo=document.getElementById('months');if(!sm||!mo)return;const want=left[Number(sm.value)||9];if(Number(mo.value)!==want){mo.value=want;mo.dispatchEvent(new Event('input',{bubbles:true}));return}const s=state();T('startMonthVal',names[s.start]);T('monthsVal',s.months+' tháng');const siteOut=document.getElementById('qaSiteOut')||document.getElementById('siteSupportFeeOut');if(siteOut)siteOut.textContent=scope()==='multi_school'?'Không áp dụng':M(s.site);const row=document.getElementById('qaSiteRow')||document.getElementById('siteSupportFeeRow');if(row){const td=row.querySelector('td');if(td)td.textContent='Phí đồng hành điểm triển khai bổ sung (từ điểm thứ 2)'}
const receipts=s.blocked?null:s.pf+s.training+s.assessment+s.site+s.recovery+s.serviceFee,total=s.blocked?null:receipts+s.equipmentSale,remain=s.blocked?null:s.parent-s.teacher-receipts-s.schoolInvest-s.other;if(s.blocked){T('sunbotTotalOut','Phương án riêng');T('sunbotTotalTable','Phương án riêng');T('remaining','Chưa kết luận')}else{T('sunbotTotalOut',M(total));T('sunbotTotalTable',M(total));T('remaining',M(remain));T('schoolLiveSunbot',M(total));T('schoolLiveRemaining',M(remain));T('capitalRecoveryOut',M(s.recovery))}
document.querySelectorAll('.stat span').forEach(e=>{if(e.textContent.trim()==='Tổng tiền vào Sunbot năm đầu')e.textContent='Tổng thanh toán Sunbot trong năm học này'});document.querySelectorAll('.liveMetric span').forEach(e=>{if(e.textContent.trim()==='Thanh toán Sunbot năm đầu')e.textContent='Thanh toán Sunbot trong năm học này'});const th=document.getElementById('sunbotTotalTable')?.closest('tr')?.querySelector('th:first-child');if(th)th.textContent='Tổng trường thanh toán Sunbot trong năm học này';
const cs=chunks(s.months),rows=[];let cur=s.start;if(!s.blocked){const pm=s.pf/s.months,smn=s.site/s.months;cs.forEach((n,i)=>{const recurring=(pm+smn+s.serviceMonthly+s.recoveryMonthly)*n,once=i===0?s.training+s.assessment+s.equipmentSale:0;rows.push({i:i+1,n,lab:label(cur,n),program:pm*n,site:smn*n,service:s.serviceMonthly*n,recovery:s.recoveryMonthly*n,once,total:recurring+once});for(let k=0;k<n;k++)cur=nx(cur)})}T('payIntro',s.blocked?'Cần lập phương án riêng trước khi sinh lịch thanh toán.':`Bắt đầu ${names[s.start].toLowerCase()}, còn ${s.months} tháng đến hết tháng 5 → ${rows.length} kỳ. Đào tạo và sát hạch thu ở kỳ đầu.`);const body=document.getElementById('payBody');if(body)body.innerHTML=s.blocked?'<tr><td colspan="3">Phương án riêng</td></tr>':rows.map(r=>`<tr><td>Kỳ ${r.i}</td><td>${r.lab} (${r.n} tháng)</td><td><b>${M(r.total)}</b><div class="sub">Chương trình ${M(r.program)}${r.site?` · Đồng hành điểm ${M(r.site)}`:''}${r.service?` · Dịch vụ ${M(r.service)}`:''}${r.recovery?` · Thu hồi vốn ${M(r.recovery)}`:''}${r.once?` · Khởi tạo/thiết bị ${M(r.once)}`:''}</div></td></tr>`).join('');T('payAfter',s.blocked?'':s.share>0?`Sau hết tháng 5, khoản vốn thiết bị còn tiếp tục ${s.remainingMonths} tháng theo kỳ hạn ${s.tm} tháng kể từ lúc bàn giao, khoảng ${M(s.recoveryMonthly)}/tháng. Nghĩa vụ thu hồi vốn không kết thúc theo năm học.`:'Nhà trường đầu tư phần thiết bị của mình ngay từ đầu; không phát sinh thu hồi vốn thiết bị của Sunbot.');
const cmp=document.getElementById('compareBody');if(cmp)cmp.innerHTML=[4,6,8].map(x=>{const rev=s.c*s.f*x*s.months*s.p+s.c*s.sv*1000*s.months,tc=s.classes*x*s.months*s.tr*s.p,pf=typeof feeByScale==='function'?feeByScale(s.c,x,s.months):null;if(s.blocked||pf===null)return `<tr><td>${x} tiết/tháng</td><td>${M(rev)}</td><td>${M(tc)}</td><td>Phương án riêng</td></tr>`;const rr=pf+s.training+s.assessment+s.site+s.recovery+s.serviceFee,rm=rev-tc-rr-s.schoolInvest-s.other;return `<tr><td>${x} tiết/tháng</td><td>${M(rev)}</td><td>${M(tc)}</td><td>${M(rm)}</td></tr>`}).join('')}
let lock=false;function sched(){if(lock)return;lock=true;setTimeout(()=>{lock=false;update()},150)}document.addEventListener('input',sched,true);document.addEventListener('change',sched,true);document.addEventListener('click',sched,true);add();update();
})();